// One tmux invocation against a session's recorded server.
//
// [LAW:one-source-of-truth] The slash edge, pane renderer and tmux
// segment's session lookup all address the pane a client reported
// (src/tmux-hint.ts); this is the one place that spells `tmux -S <socket>`,
// its timeout, and how a failure reads.

import {
  failureText,
  launcherIn,
  OWNER_CONTEXT,
  type LaunchContext,
  type ContextualLauncher,
  type LaunchCategory,
  type LaunchOpts,
  type LaunchResult,
  type Launcher,
} from "./launcher.js";
import type { TmuxHint } from "../tmux-hint.js";

// The host's named hook slots are internal. Window observers can distinguish
// their installation and retirement from a user changing a geometry hook.
export const serverObserverHookPrefix = "ccb_observer_";

// `rate-limited`: launch.ts refused to spawn, so tmux never ran — a fact about
// the caller's cadence, not about tmux.
export type TmuxRun =
  | { readonly kind: "ok"; readonly stdout: string }
  | { readonly kind: "rate-limited"; readonly reason: string }
  | {
      readonly kind: "failed";
      readonly reason: string;
      readonly serverGone?: true;
    };

function invocation(
  hint: Pick<TmuxHint, "socket">,
  category: LaunchCategory,
  args: readonly string[],
  stdinInput?: string,
): Omit<LaunchOpts, keyof LaunchContext> {
  return {
    bin: "tmux",
    args: ["-S", hint.socket, ...args],
    timeoutMs: 2000,
    category,
    stdinInput,
  };
}

function tmuxRun(
  result: LaunchResult,
  args: readonly string[],
  socket: string,
): TmuxRun {
  if (result.ok) return { kind: "ok", stdout: result.stdout };
  if (result.reason === "rate-limited") {
    return { kind: "rate-limited", reason: failureText(result) };
  }
  // Only tmux reporting this exact socket absent proves that its panes and
  // hooks are gone. Spawn errors and permission failures need recovery.
  const detail = result.stderr.trim();
  const serverGone =
    result.reason === "non-zero" &&
    (detail === `no server running on ${socket}` ||
      detail === `error connecting to ${socket} (No such file or directory)` ||
      detail === `error connecting to ${socket} (Connection refused)`);
  return {
    kind: "failed",
    ...(serverGone && { serverGone: true }),
    reason: `tmux ${args[0]} failed (${failureText(result)})`,
  };
}

// One tmux invocation, off the loop.
export async function runTmuxAsync(
  launcher: Pick<Launcher, "launch">,
  hint: Pick<TmuxHint, "socket">,
  category: LaunchCategory,
  args: readonly string[],
  stdinInput?: string,
): Promise<TmuxRun> {
  return runTmuxIn(
    launcherIn(launcher, OWNER_CONTEXT),
    hint,
    category,
    args,
    stdinInput,
  );
}

export async function runTmuxIn(
  launcher: ContextualLauncher,
  hint: Pick<TmuxHint, "socket">,
  category: LaunchCategory,
  args: readonly string[],
  stdinInput?: string,
): Promise<TmuxRun> {
  return tmuxRun(
    await launcher.launch(invocation(hint, category, args, stdinInput)),
    args,
    hint.socket,
  );
}
