import { setDataProperty } from "#packages/ecma262-abstract/intrinsics.js";
import "#packages/ecma402-abstract/types/date-time.js";
import "#packages/ecma402-abstract/DateTimeFormat/FormatDateTimePattern.js";
import { PartitionDateTimeRangePattern } from "#packages/ecma402-abstract/DateTimeFormat/PartitionDateTimeRangePattern.js";
import "#packages/ecma402-abstract/DateTimeFormat/ToLocalTime.js";
// Temporal amendment §15.6.10: project parts from the prepared range.
// https://tc39.es/proposal-temporal/#sec-formatdatetimerangetoparts
// ECMA-402 §11.5.10 projects the partition with each part’s source.
// https://tc39.es/ecma402/#sec-formatdatetimerangetoparts
export function FormatDateTimeRangeToParts(dtf, x, y, implDetails) {
	const parts = PartitionDateTimeRangePattern(dtf, x, y, implDetails);
	const result = [];
	// Temporal comparison §15.6.10 steps4–4.e: own type/value/source projection.
	for (let index = 0; index < parts.length; index++) {
		const part = parts[index];
		setDataProperty(result, `${index}`, {
			type: part.type,
			value: part.value,
			source: part.source
		});
	}
	return result;
}
